def right_angle_triangle(a, b, c):
    return (
        a * a == b * b + c * c
        or b * b == a * a + c * c
        or c * c == a * a + b * b
    )


# CPython raises OverflowError when a later mixed operation attempts to coerce
# this unbounded integer to a binary64 float.  The supplied MPY model declares
# intToF total and has no corresponding exception transition.
result = right_angle_triangle(10 ** 400, 1.0, 1.0)

